gradient pinkMetal linear 130 { stop 0 #FFEFFF; stop 0.32 #BBA7D2; stop 0.48 #FFFFFF; stop 0.52 #A77FBE; stop 0.75 #EDE9FF; stop 1 #9784B6 }
path star { move 48 2; curve 52 31 59 42 94 48; curve 61 53 54 62 48 94; curve 42 63 34 55 2 48; curve 32 43 41 32 48 2; close; fill chrome; stroke #63718A 0.8; cap round; }
path fold { move 48 2; line 48 48; line 2 48; curve 32 43 41 32 48 2; close; fill pinkMetal; }
path glint { move 49 14; line 49 45; line 79 48; fill none; stroke #FFFFFF 1.5; cap round; }
